import re
from pypdf import PdfReader
files = ['datapaper.pdf', 'methodpaper.pdf', 'ChenLiuEtAl2023_SpikeSortingQC.pdf']
patterns = [
    '69,943', '69943', '173 behavioral sessions', '173 sessions', '174', '28 mice', '28',
    '84% correct', '84 %', '476', '655 probe insertions', '25.9 %', '25.9%',
    'accuracy', 'accuracies', 'decoder', 'decoding', 'AUC', 'balanced', 'choice', 'early lick', 'tongue'
]
for file in files:
    print(f'===== {file} =====')
    reader = PdfReader(file)
    for page_num, page in enumerate(reader.pages):
        try:
            text = page.extract_text() or ''
        except Exception:
            continue
        lower = text.lower()
        hits = []
        for pat in patterns:
            if pat.lower() in lower:
                hits.append(pat)
        if hits:
            print(f'--- page {page_num+1}: hits {sorted(set(hits))}')
            lines = [ln.strip() for ln in text.splitlines() if ln.strip()]
            for ln in lines:
                l = ln.lower()
                if any(p.lower() in l for p in hits):
                    print(ln[:300])
    print()
