from pypdf import PdfReader
files = ['datapaper.pdf', 'methodpaper.pdf', 'ChenLiuEtAl2023_SpikeSortingQC.pdf']
queries = {
    'datapaper.pdf': ['69,943', '69943', '173 behavioral sessions', '173', '28 mice', '84%', '476', '655 probe', '25.9', 'good units', 'session', 'trial', 'correct rate'],
    'methodpaper.pdf': ['choice', 'AUC', 'decoder', 'decoding', 'accuracy', 'accuracies', 'movement', 'trial type', 'regular trials'],
    'ChenLiuEtAl2023_SpikeSortingQC.pdf': ['logistic regression', 'classifier', 'good', 'quality metrics', 'cross-validation', 'false alarm']
}
for file in files:
    print(f'===== {file} =====')
    reader = PdfReader(file)
    qs = [q.lower() for q in queries[file]]
    for page_num, page in enumerate(reader.pages, start=1):
        try:
            text = page.extract_text() or ''
        except Exception:
            continue
        lower = text.lower()
        if any(q in lower for q in qs):
            print(f'--- page {page_num}')
            compact = ' '.join(text.split())
            for q in qs:
                idx = lower.find(q)
                if idx != -1:
                    snippet = compact[max(0, idx-180): idx+220]
                    print(f'[{q}] ...{snippet}...')
    print()
